#[test]fn real_http_fixture_persists_accounting_and_reply_only_in_private_goal_context(){let(f,_a,g,_p,o,_main)=setup("ollama");let(server,worker)=fixture(vec![("application/json",local_metadata().to_string()),("text/event-stream",stream("<think>private reasoning</think>Hello",true))]);let mut config=crate::pet_config::defaults();config.pets.get_mut("ai_ollama").unwrap().name="Lume".into();let text=run(o.respond_once(None,&g,&server,"respond-one",&config)).unwrap();assert_eq!(text,"Hello");let requests=worker.join().unwrap();assert_eq!(requests.len(),2);assert_eq!(requests[0].0,"/api/show");assert_eq!(requests[1].0,"/v1/chat/completions");assert_eq!(requests[1].1["model"],"fixture-free");assert!(requests[1].1["messages"][0]["content"].as_str().unwrap().contains("Lume"));assert!(requests[1].1.get("tools").is_none());let reviewed:Value=serde_json::from_str(requests[1].1["messages"].as_array().unwrap().last().unwrap()["content"].as_str().unwrap()).unwrap();assert_eq!(reviewed["intent"],g.spec.intent);assert_eq!(reviewed["criteria"],json!(g.spec.criteria));assert_eq!(reviewed["toolExecutionAuthorized"],false);let rows=ledger(&f,&g);assert_eq!(rows["attempts"][0]["phase"],"settled");assert_eq!(rows["attempts"][0]["acceptedOutput"],"<think>private reasoning</think>Hello".len());assert!(!f.path.join("live-main.json").exists());assert!(std::fs::read_to_string(f.path.join("contexts").join(&g.id).join("conversation.json")).unwrap().contains("Hello"));assert_eq!(f.store().read(&g.id,"ai_ollama").unwrap().state,State::Leased);assert_eq!(o.workers(),0);assert!(o.current(crate::assistant_memory::now()));}
#[test]fn incomplete_stream_has_no_reply_commit_and_preserves_uncertain_output_reservation(){let(f,_a,g,_p,o,_main)=setup("ollama");let(server,worker)=fixture(vec![("application/json",local_metadata().to_string()),("text/event-stream",stream("Partial",false))]);assert!(run(o.respond_once(None,&g,&server,"respond-one",&crate::pet_config::defaults())).is_err());assert_eq!(worker.join().unwrap().len(),2);let rows=ledger(&f,&g);assert_eq!(rows["attempts"][0]["phase"],"uncertain");assert!(rows["attempts"][0]["acceptedOutput"].is_null());assert_eq!(rows["attempts"][0]["outputReserved"],4096);}
#[test]fn output_limit_is_checked_before_publishing_a_delta_or_committing_reply(){let(f,_a,g,_p,o,_main)=setup("ollama");let call=o.prepare_model("first",&g,4,crate::assistant_memory::now()).unwrap();let(server,worker)=fixture(vec![("text/event-stream",stream("12345",true))]);let channel=call.reservation.channel();assert!(run(crate::local_chat::send_runtime_once(None,&channel,&server,"fixture-free",g.spec.intent.clone(),g.spec.intent.clone(),&call,&crate::pet_config::defaults())).is_err());assert_eq!(worker.join().unwrap().len(),1);call.finish(None).unwrap();assert_eq!(ledger(&f,&g)["attempts"][0]["phase"],"uncertain");assert_eq!(ledger(&f,&g)["attempts"][0]["outputReserved"],4);}
